using OcctSharp.LocalStepExports;
using OcctSharp.DocumentProjections;
using OcctSharp.StepCafWorkspaces;
using OcctSharp.XdeMetadataWorkspaces;
using OcctSharp.XdeAttributeProjections;
namespace OcctSharp.Tests.Shared;
internal static class BatchBPLocalExportWorkflow {
 internal static void Require(bool value,string detail){if(!value)throw new InvalidOperationException("BP: "+detail);}
 internal static StepCafReadResult Source(string directory,double height=2)=>StepCafFiles.Read(BatchBPRawSourceDocument.Create(directory,height));
 internal static void Verify(LocalStepExportResult written,int rootCount=1,int occurrences=3){written.Validate();Require(written.Files.Count==3&&written.Files[0].FileName=="assembly.step"&&written.Files.Skip(1).All(x=>x.FileName.StartsWith("part-",StringComparison.Ordinal)&&x.SourceDefinitionEntry.Length>0),"canonical complete three-file set");using var workspace=written.OpenForReadback();Require(workspace.Roots.Count==rootCount,"actual new multi-file root count");using var restored=workspace.Transfer(workspace.Roots.Select(x=>x.Id));Require(restored.Completed&&restored.Document is not null&&restored.FreeRoots.Count==rootCount&&restored.Occurrences.Count==occurrences,"actual BJ transfer of new output");var groups=restored.Occurrences.GroupBy(x=>x.DefinitionEntry).OrderByDescending(x=>x.Count()).ToArray();Require(groups.Length==2&&groups[0].Count()==occurrences-1,"exact repeated/shared definitions after readback");Require(restored.Files.Skip(1).All(x=>x.Loaded&&x.LoadStatus==1&&x.NativeTransferSucceeded==true),"actual external load/transfer status");using var context=DocumentProjectionContext.Bind(restored.Document!);using var metadata=XdeMetadataContext.Bind(context);using var layers=XdeAttributeProjectionContext.Bind(context);var shared=context.GetLabel(groups[0].Key);var target=metadata.Snapshot([shared]).Targets.Single();var color=target.General??target.Surface;Require(color is not null&&Math.Abs(color.Red-.2)<1e-6&&Math.Abs(color.Green-.3)<1e-6&&Math.Abs(color.Blue-.4)<1e-6,"actual external definition color (STEP general/surface channel)");Require(layers.Snapshot(shared).Layers.Any(x=>x.Name=="本轮图层"&&x.AssociatedEntries.Contains(shared.Entry)),"actual external definition Unicode layer");foreach(var file in written.Files.Skip(1)){using var part=StepCafFiles.Read(Path.Combine(written.DirectoryPath,file.FileName));Require(part.Diagnostics.FreeRoots.Count==1&&part.Diagnostics.FreeRoots[0].Name==BatchBPRawSourceDocument.ModelName,"actual same Unicode part names independent from canonical filenames");}using var shape=restored.CopyFreeRoot(1);Require(shape.IsValid&&shape.FaceCount==18,"new BL solids actual assembled topology");var copies=groups[0].Select(x=>restored.Occurrences.ToList().FindIndex(y=>y.Entry==x.Entry)+1).Take(2).ToArray();if(rootCount==1){using var a=restored.CopyOccurrence(copies[0]);using var b=restored.CopyOccurrence(copies[1]);Require(Math.Abs(Math.Abs(a.GetBoundingBox().Minimum.X-b.GetBoundingBox().Minimum.X)-10)<1e-5,"exact repeated occurrence placement");}}
 internal static void Run(){string directory=Path.Combine(Path.GetTempPath(),"OcctSharp.BP."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{using var source=Source(directory);Require(source.Diagnostics.FreeRoots.Count==2,"two new BL source assembly roots");using var context=DocumentProjectionContext.Bind(source.Document);var selected=context.GetLabel(source.Diagnostics.FreeRoots.Single(x=>x.Name==BatchBNBoundedTextWorkflow.Names()[0]).Entry);var written=LocalStepAssemblyExport.Export(context,[selected],Path.Combine(directory,"导出 多文件 🚀"));Require(written.Selected.Single().SourceEntry==selected.Entry&&written.Selected.Single().ModelName==BatchBNBoundedTextWorkflow.Names()[0],"exact selected Unicode root diagnostics");source.Dispose();Verify(written);}
 finally{Directory.Delete(directory,true);}}
}
